41	  | { readonly kind: "eat-completed"; readonly tick: number; readonly playerId: string; readonly pedestalId: string; readonly kit: FruitKitId }
42	  /** A tick not later than the state's: nothing is applied and the very same state comes back. */
43	  | { readonly kind: "tick-rejected"; readonly tick: number; readonly lastTick: number };
