73	/**
74	 * One world tick of §9's acquisition rules. A tick not later than the state's is rejected with the very same state.
75	 * Otherwise, in a fixed order: (1) a skipped tick resets every channel (`gap`); (2) players, sorted by id, advance,
76	 * start, reset or are refused, and channels of players absent from the facts are released; (3) channels that reach
77	 * `eatTicks` complete in id order: the first eats the fruit, and every later completer, and every other channel at
78	 * that pedestal, is interrupted as `taken`. The input and the state are never mutated.
79	 */
80	export function stepFruits(config: FruitConfig, state: FruitState, input: FruitTickInput): FruitStepResult {
81	  if (typeof input.tick !== "number" || !Number.isSafeInteger(input.tick)) throw new RangeError(`tick must be a safe integer, got ${String(input.tick)}`);
82	  if (input.tick <= state.tick) return { state, results: [{ kind: "tick-rejected", tick: input.tick, lastTick: state.tick }] };
