87	    kind: "eat-interrupted",
88	    tick,
89	    playerId: channel.playerId,
90	    pedestalId: channel.pedestalId,
91	    reason,
92	    held: channel.held,
93	  });
94	
95	  const pedestals = new Map(state.pedestals.map((pedestal) => [pedestal.id, pedestal]));
96	  const fed = new Set(state.meals.map((meal) => meal.playerId));
97	  const previous = new Map(state.channels.map((channel) => [channel.playerId, channel]));
98	  const present = new Set(players.map((player) => player.playerId));
99	  const gap = tick !== state.tick + 1;
100	
101	  // Each player's step, and the released channels of absent players, merged in id order.
102	  const steps: { playerId: string; results: FruitResult[]; channel: FruitChannel | null }[] = [];
103	  for (const channel of state.channels) {
104	    if (!present.has(channel.playerId)) steps.push({ playerId: channel.playerId, results: [interrupted(channel, gap ? "gap" : "released")], channel: null });
105	  }
106	  for (const player of players) {
107	    const own: FruitResult[] = [];
108	    let channel = previous.get(player.playerId) ?? null;
109	    // 1. A skipped tick breaks every channel.
110	    if (channel !== null && gap) {
111	      own.push(interrupted(channel, "gap"));
112	      channel = null;
113	    }
114	    const target = player.holding ? player.pedestalId : null;
115	    if (target === null) {
116	      if (channel !== null) own.push(interrupted(channel, "released"));
117	      steps.push({ playerId: player.playerId, results: own, channel: null });
118	      continue;
119	    }
120	    if (channel !== null && channel.pedestalId !== target) {
121	      own.push(interrupted(channel, "moved"));
122	      channel = null;
123	    }
124	    const pedestal = pedestals.get(target)!;
125	    const refusal: FruitRefusalReason | null = player.left
126	      ? "left"
127	      : player.disconnected
128	        ? "disconnected"
129	        : player.reserved
130	          ? "reserved"
131	          : fed.has(player.playerId)
132	            ? "already-eaten"
133	            : pedestal.eatenBy !== null
134	              ? "empty"
135	              : null;
136	    if (refusal !== null) {
137	      // A live channel can only meet the player's own state here: a fed player or an empty pedestal has none.
138	      if (channel !== null) own.push(interrupted(channel, refusal as FruitInterruptReason));
139	      else own.push({ kind: "eat-refused", tick, playerId: player.playerId, pedestalId: target, reason: refusal });
140	      steps.push({ playerId: player.playerId, results: own, channel: null });
141	      continue;
142	    }
143	    if (channel !== null) {
144	      channel = { ...channel, lastTick: tick, held: channel.held + 1 };
145	    } else {
146	      channel = { playerId: player.playerId, pedestalId: target, startTick: tick, lastTick: tick, held: 1 };
147	      own.push({ kind: "eat-started", tick, playerId: player.playerId, pedestalId: target });
148	    }
149	    steps.push({ playerId: player.playerId, results: own, channel });
150	  }
151	  steps.sort((a, b) => compareIds(a.playerId, b.playerId));
152	  for (const step of steps) results.push(...step.results);
153	
154	  // 2. Completions in id order: the lowest id eats; the rest at that pedestal find it taken.
155	  const meals: FruitMeal[] = [...state.meals];
156	  let channels = steps.flatMap((step) => (step.channel === null ? [] : [step.channel]));
157	  for (const channel of channels) {
158	    if (channel.held < config.eatTicks) continue;
159	    const pedestal = pedestals.get(channel.pedestalId)!;
160	    if (pedestal.eatenBy !== null) continue;
161	    pedestals.set(pedestal.id, { ...pedestal, eatenBy: channel.playerId });
162	    meals.push({ playerId: channel.playerId, pedestalId: pedestal.id, kit: pedestal.kit, tick });
163	    results.push({ kind: "eat-completed", tick, playerId: channel.playerId, pedestalId: pedestal.id, kit: pedestal.kit });
164	  }
165	  const eatenNow = new Set(meals.slice(state.meals.length).map((meal) => meal.pedestalId));
166	  const eaters = new Set(meals.slice(state.meals.length).map((meal) => meal.playerId));
167	  channels = channels.filter((channel) => {
168	    if (eaters.has(channel.playerId)) return false;
169	    if (!eatenNow.has(channel.pedestalId)) return true;
170	    results.push(interrupted(channel, "taken"));
171	    return false;
172	  });
173	
174	  meals.sort((a, b) => compareIds(a.playerId, b.playerId));
175	  const next: FruitState = {
176	    tick,
177	    pedestals: state.pedestals.map((pedestal) => pedestals.get(pedestal.id)!),
178	    channels,
179	    meals,
180	  };
181	  return { state: next, results };
182	}
