190	/** Steps a sequence of ticks from a state, collecting every result; `hash` is the final state's `hashState`. */
191	export function replayFruits(config: FruitConfig, state: FruitState, inputs: readonly FruitTickInput[]): FruitReplay {
192	  let current = state;
193	  const results: FruitResult[] = [];
194	  for (const input of inputs) {
195	    const stepped = stepFruits(config, current, input);
196	    current = stepped.state;
197	    results.push(...stepped.results);
198	  }
199	  return { state: current, results, hash: hashState(current) };
200	}
