202	/** Invariant violations of a fruit state, empty when it is consistent. */
203	export function checkFruitState(state: FruitState): string[] {
204	  const issues: string[] = [];
205	  const pedestals = new Map<string, FruitPedestal>(state.pedestals.map((pedestal) => [pedestal.id, pedestal]));
206	  const eatenPedestals = new Set<string>();
207	  const fedPlayers = new Set<string>();
208	  for (const meal of state.meals) {
209	    if (fedPlayers.has(meal.playerId)) issues.push(`player ${meal.playerId} ate twice`);
210	    fedPlayers.add(meal.playerId);
211	    if (eatenPedestals.has(meal.pedestalId)) issues.push(`pedestal ${meal.pedestalId} was eaten twice`);
212	    eatenPedestals.add(meal.pedestalId);
213	    const pedestal = pedestals.get(meal.pedestalId);
214	    if (pedestal === undefined) issues.push(`meal at unknown pedestal ${meal.pedestalId}`);
215	    else if (pedestal.eatenBy !== meal.playerId || pedestal.kit !== meal.kit) issues.push(`pedestal ${meal.pedestalId} disagrees with ${meal.playerId}'s meal`);
216	  }
217	  const full = state.pedestals.filter((pedestal) => pedestal.eatenBy === null).length;
