85	export function fruitDeck(preset: RulesPreset, pedestalsPerKit: number): FruitKitId[] {
86	  if (preset.fruitKits !== FRUIT_KIT_IDS.length) {
87	    throw new RangeError(
88	      `the ${preset.id} preset deals ${preset.fruitKits} fruit kits, but only ${FRUIT_KIT_IDS.length} exist (${FRUIT_KIT_IDS.join(", ")})`,
