138	 * never seen. Nothing in this module clears a meal, so a defeat or leaving keeps it.
139	 */
140	export function kitOf(state: FruitState, playerId: string): KitId {
141	  return state.meals.find((meal) => meal.playerId === playerId)?.kit ?? "duelist";
142	}
