1	import { rulesPresets, seaPathCosts, type RulesPresetId, type SeaMapDefinition } from "@pirate-sea-race/content";
2	import { sourceId } from "@pirate-sea-race/content/objectives";
3	import {
4	  cacheRubbings,
5	  createLedger,
6	  createLedgerFromAssignment,
7	  heldTypes,
8	  RUBBING_TYPES,
9	  type LedgerCache,
10	  type LedgerState,
11	  type ObjectiveRules,
12	  type RubbingType,
13	  type SourceAssignment,
14	  type SourceSite,
15	} from "@pirate-sea-race/simulation/objectives";
16	
17	/**
18	 * The room's side of the objective ledger (`docs/objectives.md`): where the sources stand on the sea, what interact
19	 * (E) targets at a dock, and where a leaver's recovery cache goes. The ledger itself decides every move of a rubbing
20	 * or of gold; nothing here writes one.
21	 */
22	
23	/** Private matches play the slice preset (§18 stage 2): two types, eight rubbings, two sources on each of four islands. */
24	export const MATCH_PRESET: RulesPresetId = "slice";
25	
26	/** The centre of a dock's tile, in sub-units: where a moored ship lies, a source stands and a cache is placed. */
27	export function dockCentre(map: SeaMapDefinition, dockId: number): { x: number; y: number } {
28	  const dock = map.docks[dockId];
29	  if (dock === undefined) throw new RangeError(`no dock ${dockId}`);
30	  const half = Math.floor(map.subUnitsPerTile / 2);
31	  return { x: dock.tileX * map.subUnitsPerTile + half, y: dock.tileY * map.subUnitsPerTile + half };
32	}
33	
34	/** An island's docks, in id order. */
35	export function islandDocks(map: SeaMapDefinition, island: number): number[] {
36	  return map.docks.filter((dock) => dock.island === island).map((dock) => dock.id);
37	}
38	
39	/**
40	 * The ledger's source sites: `sourcesPerIsland` on each regular island, at that island's docks taken in id order (a
41	 * dock is reused when the island has fewer docks than sources). Site `j` of island `i` becomes source `source-i-j`.
42	 */
43	export function sourceSites(map: SeaMapDefinition, presetId: RulesPresetId = MATCH_PRESET): SourceSite[] {
44	  const preset = rulesPresets[presetId];
45	  const sites: SourceSite[] = [];
46	  for (let island = 0; island < preset.islands; island++) {
47	    const docks = islandDocks(map, island);
48	    if (docks.length === 0) throw new Error(`${map.name}: island ${island} has no dock for its sources`);
49	    for (let slot = 0; slot < preset.sourcesPerIsland; slot++) sites.push({ island, ...dockCentre(map, docks[slot % docks.length]!) });
50	  }
51	  return sites;
52	}
53	
54	/**
55	 * A fixed assignment for the test-only source layout (`TEST_SOURCES_ENV`): island `i`'s sources get the types of
56	 * group `i`, in order, each the next unused copy of that type. The ledger validates the result like any assignment,
57	 * so a layout that does not seal every rubbing once is refused.
58	 */
59	export function layoutAssignment(sites: readonly SourceSite[], layout: readonly (readonly string[])[], presetId: RulesPresetId = MATCH_PRESET): SourceAssignment {
60	  const copies = new Map<string, number>();
61	  const slots = new Map<number, number>();
62	  const sources = sites.map((site) => {
63	    const slot = slots.get(site.island) ?? 0;
64	    slots.set(site.island, slot + 1);
65	    const type = layout[site.island]?.[slot];
66	    if (type === undefined || !(RUBBING_TYPES as readonly string[]).includes(type)) {
67	      throw new Error(`test source layout: island ${site.island} source ${slot} has no valid type`);
68	    }
69	    const copy = (copies.get(type) ?? 0) + 1;
70	    copies.set(type, copy);
71	    return { id: sourceId(site.island, slot), island: site.island, x: site.x, y: site.y, type: type as RubbingType, rubbingId: `${type}-${copy}` };
72	  });
73	  return { preset: presetId, seed: 0, sources };
74	}
75	
76	export interface MatchLedgerOptions {
77	  readonly map: SeaMapDefinition;
78	  /** The room's own private randomness, never the public match code (§3, §16). */
79	  readonly seed: number;
80	  readonly rules: ObjectiveRules;
81	  /** Test-only: deal the sources in this layout instead of shuffling them. */
82	  readonly layout?: readonly (readonly string[])[];
83	}
84	
85	/**
86	 * A new match's ledger. Every source starts locked behind its island's ruin (§3): the first solve of that ruin unlocks
87	 * them (`ruins-online`).
88	 */
89	export function createMatchLedger(options: MatchLedgerOptions): LedgerState {
90	  const sites = sourceSites(options.map);
91	  return options.layout === undefined
92	    ? createLedger({ preset: MATCH_PRESET, seed: options.seed, sites, rules: options.rules })
93	    : createLedgerFromAssignment(layoutAssignment(sites, options.layout), options.seed >>> 0, options.rules);
94	}
95	
96	const typeOrder = (type: RubbingType) => RUBBING_TYPES.indexOf(type);
97	
98	/** The types still sealed at an island's sources, one per source, in type order: what a moored player may see there. */
99	export function sealedTypesAt(ledger: LedgerState, island: number): RubbingType[] {
100	  return ledger.sources
101	    .filter((source) => source.island === island && sealedAt(ledger, source.id, source.rubbingId))
102	    .map((source) => source.type)
103	    .sort((a, b) => typeOrder(a) - typeOrder(b));
104	}
105	
106	function sealedAt(ledger: LedgerState, sourceIdentifier: string, rubbingId: string): boolean {
107	  const rubbing = ledger.rubbings.find((each) => each.id === rubbingId);
108	  return rubbing?.location.kind === "source" && rubbing.location.sourceId === sourceIdentifier;
109	}
110	
111	/** The dock a cache stands at (caches are only ever placed at dock centres), or -1. */
112	export function cacheDock(map: SeaMapDefinition, cache: Pick<LedgerCache, "x" | "y">): number {
113	  for (const dock of map.docks) {
114	    const centre = dockCentre(map, dock.id);
115	    if (centre.x === cache.x && centre.y === cache.y) return dock.id;
116	  }
117	  return -1;
118	}
119	
120	/** The caches at a dock, in creation order. */
121	export function cachesAtDock(ledger: LedgerState, map: SeaMapDefinition, dockId: number): LedgerCache[] {
122	  return ledger.caches.filter((cache) => cacheDock(map, cache) === dockId);
123	}
124	
125	/** The types held in the caches at a dock, one per rubbing, in type order: what a player moored there may see. */
126	export function cachedTypesAt(ledger: LedgerState, map: SeaMapDefinition, dockId: number): RubbingType[] {
127	  return cachesAtDock(ledger, map, dockId)
128	    .flatMap((cache) => cacheRubbings(ledger, cache.id).map((rubbing) => rubbing.type))
129	    .sort((a, b) => typeOrder(a) - typeOrder(b));
130	}
131	
132	/** What holding E at a dock works on: an island source to collect, or one cached rubbing to claim. */
133	export type InteractTarget =
134	  | { readonly kind: "collect"; readonly sourceId: string; readonly type: RubbingType }
135	  | { readonly kind: "claim"; readonly cacheId: string; readonly rubbingId: string; readonly type: RubbingType };
136	
137	/**
138	 * E's target for a player moored at a dock: first the island's unlocked sealed source of a type the player lacks,
139	 * then a rubbing of a type they lack in a cache at this dock, each in the fixed type order (ties to the lower source
140	 * id, the older cache, the lower rubbing id). None when the player lacks nothing on offer.
141	 */
142	export function interactTarget(ledger: LedgerState, map: SeaMapDefinition, playerId: string, dockId: number): InteractTarget | undefined {
143	  const island = map.docks[dockId]?.island;
144	  if (island === undefined || island < 0) return undefined;
145	  const held = new Set(heldTypes(ledger, playerId));
146	  const source = ledger.sources
147	    .filter((each) => each.island === island && each.unlocked && !held.has(each.type) && sealedAt(ledger, each.id, each.rubbingId))
148	    .sort((a, b) => typeOrder(a.type) - typeOrder(b.type) || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))[0];
149	  if (source !== undefined) return { kind: "collect", sourceId: source.id, type: source.type };
150	  for (const type of ledger.types) {
151	    if (held.has(type)) continue;
152	    for (const cache of cachesAtDock(ledger, map, dockId)) {
153	      const rubbing = cacheRubbings(ledger, cache.id)
154	        .filter((each) => each.type === type)
155	        .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))[0];
156	      if (rubbing !== undefined) return { kind: "claim", cacheId: cache.id, rubbingId: rubbing.id, type };
157	    }
158	  }
159	  return undefined;
160	}
161	
162	/**
163	 * The dock nearest a position by sea (§12: a quitter's cache goes to the nearest reachable dock): the shortest
164	 * eight-way path over navigable tiles, ties to the lower dock id. A position whose tile reaches no dock falls back to
165	 * the nearest dock in a straight line.
166	 */
167	export function nearestDockBySea(map: SeaMapDefinition, x: number, y: number): number {
168	  const tileX = Math.floor(x / map.subUnitsPerTile);
169	  const tileY = Math.floor(y / map.subUnitsPerTile);
170	  const costs = seaPathCosts(map, tileX, tileY);
171	  let best = -1;
172	  let bestCost = Number.POSITIVE_INFINITY;
173	  for (const dock of map.docks) {
174	    const cost = costs[dock.tileY * map.widthTiles + dock.tileX]!;
175	    if (cost < bestCost) {
176	      best = dock.id;
177	      bestCost = cost;
178	    }
179	  }
180	  if (best >= 0 && bestCost < Number.MAX_SAFE_INTEGER) return best;
181	  let nearest = 0;
182	  let nearestDistance = Number.POSITIVE_INFINITY;
183	  for (const dock of map.docks) {
184	    const centre = dockCentre(map, dock.id);
185	    const distance = (centre.x - x) ** 2 + (centre.y - y) ** 2;
186	    if (distance < nearestDistance) {
187	      nearest = dock.id;
188	      nearestDistance = distance;
189	    }
190	  }
191	  return nearest;
192	}
