1	import { matchMaker } from "colyseus";
2	import { expect } from "vitest";
3	import { isNavigable, seaMap } from "@pirate-sea-race/content";
4	import { encounterRules, type EncounterRules } from "@pirate-sea-race/content/encounters";
5	import { matchRules } from "@pirate-sea-race/content/match";
6	import type { MatchRoom, MatchTuning } from "@pirate-sea-race/server";
7	import { defaultSimulationConfig, hullPathIsClear, tileCentre } from "@pirate-sea-race/simulation";
8	import { duelInput } from "@pirate-sea-race/simulation/duel";
9	import { Buttons } from "@pirate-sea-race/protocol";
10	import { HeadlessClient, sleep, type DuelScript, type HeadlessClientOptions, type Movement } from "@pirate-sea-race/test-tools";
11	
12	/**
13	 * What the duel-at-sea tests share: the open stretch of sea they sail on, a pair of players placed on it, and the
14	 * scripted fighters. Each test file starts its own server; tests in a file run at once, one match each.
15	 */
16	
17	/** The row three tiles south of the hub, which the map keeps clear for a hull 20 tiles either side of the hub. */
18	export const OPEN_ROW = seaMap.hub.tileY + 3;
19	export const HUB_X = seaMap.hub.tileX;
20	export const TILE = seaMap.subUnitsPerTile;
21	/** Headings of 64: east, south, west, north. */
22	export const EAST = 0;
23	export const SOUTH = 16;
24	export const WEST = 32;
25	export const NORTH = 48;
26	
27	/**
28	 * Collects a test's clients and has them leave when that test finishes (tests in a file run at once). When it
29	 * finishes, and again once every client has left, it checks each match room those clients were in: the room checked
30	 * `checkLedger` and its own invariant (no ship removed while the ledger counts its player in the match, and no ship
31	 * without such a player) after every world tick, and found no violation; and the ledger refused nothing the room asked.
32	 */
33	export function tracker(onTestFinished: (fn: () => Promise<void>) => void): (client: HeadlessClient) => void {
34	  const clients: HeadlessClient[] = [];
35	  const rooms = new Set<MatchRoom>();
36	  onTestFinished(async () => {
37	    const checked = [...rooms];
38	    await Promise.all(clients.map((client) => client.leave()));
39	    await sleep(150);
40	    for (const room of checked) expectRoomChecks(room);
41	  });
42	  return (client) => {
43	    clients.push(client);
44	    const room = roomOf(client);
45	    if (room !== undefined) rooms.add(room);
46	  };
47	}
48	
49	/**
50	 * The test source layout (the server's test-only setting): Palm Key (island 0) and Old Stones (2) seal two Suns each,
51	 * Ember Rock (1) and Mist Cay (3) two Moons each, so a test picks a type by the island it moors at.
52	 */
53	export const TEST_SOURCE_LAYOUT = [
54	  ["sun", "sun"],
55	  ["moon", "moon"],
56	  ["sun", "sun"],
57	  ["moon", "moon"],
58	] as const;
59	
60	/** A dock of the island that seals `type` in the test layout: Palm Key's west dock for Sun, Ember Rock's east for Moon. */
61	export function dockFor(type: "sun" | "moon", which = 0): (typeof seaMap.docks)[number] {
62	  const islands = TEST_SOURCE_LAYOUT.flatMap((types, island) => (types[0] === type ? [island] : []));
63	  return seaMap.docks.filter((dock) => islands.includes(dock.island))[which]!;
64	}
65	
66	/** Holding E with no throttle: moors at a dock in reach, and keeps holding to collect or claim there. */
67	export const HOLD_E: Movement = { moveX: 0, moveY: 0, buttons: Buttons.Interact };
68	
69	/**
70	 * Puts a client's ship on a dock's tile, moors it there and holds E until it holds `type` (a collection, or a claim
71	 * from a cache there), then lets go.
72	 */
73	export async function collectAt(client: HeadlessClient, endpoint: string, dock: { id: number; tileX: number; tileY: number }, type: string, timeoutMs = 15_000): Promise<void> {
74	  await client.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY, heading: 0 });
75	  await client.holdUntil(HOLD_E, () => client.rubbings().includes(type), timeoutMs);
76	  expect(client.ship()?.dock).toBe(dock.id);
77	}
78	
79	/**
80	 * What `tracker` asserts of each match room, for files that clean up their own clients: the room checked
81	 * `checkLedger` and its own invariant after every world tick and found no violation, and the ledger refused nothing.
82	 */
83	export function expectRoomChecks(room: MatchRoom): void {
84	  expect(room.invariantViolations, `invariants of match ${room.state.code}`).toEqual([]);
85	  expect(room.ledgerRefusals, `ledger refusals in match ${room.state.code}`).toEqual([]);
86	}
87	
88	export function roomOf(client: HeadlessClient): MatchRoom {
89	  return matchMaker.getLocalRoomById(client.room.roomId) as unknown as MatchRoom;
90	}
91	
92	/** Resolves once `predicate` holds for the room itself (its ledger or rules state), polling; rejects after `timeoutMs`. */
93	export async function until(predicate: () => boolean, timeoutMs = 5000, what = "condition"): Promise<void> {
94	  const deadline = Date.now() + timeoutMs;
95	  while (!predicate()) {
96	    if (Date.now() > deadline) throw new Error(`${what} not met within ${timeoutMs} ms`);
97	    await sleep(10);
98	  }
99	}
100	
101	export interface Seat {
102	  readonly tileX: number;
103	  readonly tileY: number;
